K = ["hi","bn","tr","id"]
def apply(duas, phrases):
    for d in duas: d["pr"] = PR_DUA[d["id"]]
    assert len(_PH) == len(phrases), (len(_PH), len(phrases))
    for p, (m, f) in zip(phrases, _PH):
        assert (f is None) == (p["f"] is None), p["tr_"]
        p["pr"] = dict(zip(K, m))
        if f: p["prf"] = dict(zip(K, f))
